      {
        "time": 108.355,
        "end": 111.575,
        "text": "もともと しけんは きらいだよ！」",
        "section": 15,
        "translation": "我本來就討厭考試！」"
      },
      {
        "time": 111.575,
        "end": 114.015,
        "text": "「えっ？ ほんとうに いちばんに なった！",
        "section": 16,
        "translation": "「咦？真的考到第一名了！"
      },
      {
        "time": 114.015,
        "end": 115.655,
        "text": "ぼくが しけんで いちばんだ！」",
        "section": 16,
        "translation": "我考試拿了第一名！」"
      },
      {
        "time": 115.655,
        "end": 117.555,
        "text": "ごが ごとうきゅう ならば、",
        "section": 17,
        "translation": "如果五是五職等，"
      },
      {
        "time": 117.555,
        "end": 119.355,
        "text": "じゅうには じゅうにとうきゅう。",
        "section": 17,
        "translation": "十二就是十二職等。"
      },
      {
        "time": 119.355,
        "end": 121.175,
        "text": "ごじゅうには ごじゅうにさい？",
        "section": 17,
        "translation": "五十二是五十二歲嗎？"
      },
      {
        "time": 121.175,
        "end": 122.935,
        "text": "「そうでも あるし、ちがいも する！」",
        "section": 18,
        "translation": "「是，也不是！」"
      },
      {
        "time": 122.935,
        "end": 126.265,
        "text": "「いったい どういう いみなの？」",
        "section": 18,
        "translation": "「究竟是什麼意思？」"
      },
      {
        "time": 126.755,
        "end": 128.655,
        "text": "「ごじゅうにさいに なっても、",
        "section": 19,
        "translation": "「即使到了五十二歲，"
      },
      {
        "time": 128.655,
        "end": 130.575,
        "text": "じゅうにとうきゅう じゃなければ、",
        "section": 19,
        "translation": "如果還不是十二職等，"
      },
      {
        "time": 130.575,
        "end": 133.565,
        "text": "この くみあわせは おしまいだ！」",
        "section": 19,
        "translation": "這組就結束了！」"
      },
      {
        "time": 134.375,
        "end": 136.195,
        "text": "「でも じゅうにとうきゅうは、",
        "section": 20,
        "translation": "「但是十二職等，"
      },
      {
        "time": 136.195,
        "end": 137.915,
        "text": "ふくじむちょう なんだよ。",
        "section": 20,
        "translation": "是副秘書長，"
      },
      {
        "time": 137.915,
        "end": 140.625,
        "text": "しかも ごじゅうにさい じゃない！」",
        "section": 20,
        "translation": "而且不是五十二歲！」"
      },
      {
        "time": 141.335,
        "end": 143.975,
        "text": "「ほかの くみあわせも みてごらん！」",
        "section": 21,
        "translation": "「也看看其他組合吧！」"
      },
      {
        "time": 143.975,
        "end": 145.815,
        "text": "「そうだね！ まだ あるんだ！」",
        "section": 21,
        "translation": "「對耶！還有其他組！」"
      },
      {
        "time": 145.815,
        "end": 147.465,
        "text": "ごと じゅうはち、ひとくみだ、",
        "section": 22,
        "translation": "五和十八，是一組，"
      },
      {
        "time": 147.595,
        "end": 149.035,
        "text": "「いみが ないから とばそうよ！」",
        "section": 22,
        "translation": "「沒有意義，跳過吧！」"
      },
      {
        "time": 149.035,
        "end": 150.665,
        "text": "ごと にじゅうさん、ひとくみだ、",
        "section": 23,
        "translation": "五和二十三，是一組，"
      },
      {
        "time": 150.815,
        "end": 152.635,
        "text": "「ごくみの にじゅうさんばん？」",
        "section": 23,
        "translation": "「五班二十三號？」"
      },
      {
        "time": 152.635,
        "end": 154.465,
        "text": "ちゅうがくの じゅくの ともだち？",
        "section": 24,
        "translation": "國中補習班的朋友？"
      },
      {
        "time": 154.542,
        "end": 156.125,
        "text": "「それの どこが とくべつなの？」",
        "section": 24,
        "translation": "「那有什麼特別的？」"
      },
      {
        "time": 156.435,
        "end": 158.195,
        "text": "「きみは どう おもう？」",
        "section": 25,
        "translation": "「你怎麼想？」"
      },
      {
        "time": 158.415,
        "end": 159.985,
        "text": "「かのじょは こうむいんなの？」",
        "section": 25,
        "translation": "「她是公務人員嗎？」"
      },
      {
        "time": 160.239,
        "end": 161.813,
        "text": "「せいしきな しょくいん じゃない！」",
        "section": 26,
        "translation": "「不是正式職員！」"
      },
      {
        "time": 162.295,
        "end": 163.885,
        "text": "「じゃあ けいやくしょくいん？」",
        "section": 26,
        "translation": "「那就是約聘人員？」"
      },
      {
        "time": 163.885,
        "end": 165.615,
        "text": "「いつか わかる ときが くる、",
        "section": 27,
        "translation": "「總有一天會明白，"
      },
      {
        "time": 165.615,
        "end": 167.455,
        "text": "だから いまは おしえない！」",
        "section": 27,
        "translation": "所以現在先不告訴你！」"
      },
      {
        "time": 167.455,
        "end": 169.235,
        "text": "じゅうにと じゅうはち、ひとくみだ、",
        "section": 28,
        "translation": "十二和十八，是一組，"
      },
      {
        "time": 169.235,
        "end": 170.815,
        "text": "「しびせいじんが たいぺいの",
        "section": 28,
        "translation": "「聽說有個紫微聖人，"
      },
      {
        "time": 170.815,
        "end": 173.715,
        "text": "しちょうせんきょに でるんだって！」",
        "section": 28,
        "translation": "要參加台北市長選舉！」"
      },
      {
        "time": 173.715,
        "end": 176.335,
        "text": "「おもしろい！ なんだか ふしぎ！」",
        "section": 29,
        "translation": "「真有趣！感覺好神奇！」"
      },
      {
        "time": 176.335,
        "end": 178.395,
        "text": "にせんにじゅうにねん、",
        "section": 30,
        "translation": "二零二二年，"
      },
      {
        "time": 178.395,
        "end": 180.22,
        "text": "しちょうは だいはっき、",
        "section": 30,
        "translation": "市長是第八屆，"
      },
      {
        "time": 180.395,
        "end": 182.175,
        "text": "しぎかいは だいじゅうよんき！",
        "section": 30,
        "translation": "市議會是第十四屆！"
      },
      {
        "time": 182.175,
        "end": 183.935,
        "text": "「どちらも よんきを すすめたら、",
        "section": 31,
        "translation": "「如果兩邊都往後推四屆，"
      },
      {
        "time": 183.935,
        "end": 185.675,
        "text": "ぴったり あうんじゃ ないかな？」",
        "section": 31,
        "translation": "不就剛好對上了嗎？」"
      },
      {
        "time": 185.675,
        "end": 187.615,
        "text": "ほかの ちいきも みてみよう、",
        "section": 32,
        "translation": "也來看看其他地區，"
      },
      {
        "time": 187.615,
        "end": 189.47,
        "text": "きんもんは しちょうが だいはっき、",
        "section": 32,
        "translation": "金門的市長是第八屆，"
      },
      {
        "time": 189.555,
        "end": 191.225,
        "text": "ぎかいも だいはっき！",
        "section": 32,
        "translation": "議會也是第八屆！"
      },
      {
        "time": 191.415,
        "end": 193.05,
        "text": "れんこうも だいはっき、",
        "section": 33,
        "translation": "連江也是第八屆，"
      },
      {
        "time": 193.235,
        "end": 194.92,
        "text": "ぎかいも だいはっき！",
        "section": 33,
        "translation": "議會也是第八屆！"
      },
      {
        "time": 195.095,
        "end": 197.215,
        "text": "「ほかには ないみたいだ！」",
        "section": 34,
        "translation": "「看來沒有其他的了！」"
      },
      {
        "time": 197.215,
        "end": 199.035,
        "text": "「たいぺいの しちょう？ じょうだんでしょ！",
        "section": 35,
        "translation": "「台北市長？開玩笑的吧！"
      },
      {
        "time": 199.035,
        "end": 201.195,
        "text": "なるなら こうたいしゅう より まえの",
        "section": 35,
        "translation": "要當也想當黃大洲之前的，"
      },
      {
        "time": 201.195,
        "end": 202.155,
        "text": "しちょうに なりたい、",
        "section": 35,
        "translation": "那個時代的市長，"
      },
      {
        "time": 202.155,
        "end": 204.275,
        "text": "だいとうりょうの おうえんつきで！」",
        "section": 35,
        "translation": "有總統的支持！」"
      },
      {
        "time": 204.275,
        "end": 206.515,
        "text": "じゅうにと にじゅうさん、ひとくみだ、",
        "section": 36,
        "translation": "十二和二十三，是一組，"
      },
      {
        "time": 206.515,
        "end": 208.175,
        "text": "「いみが ないから とばそうよ！」",
        "section": 36,
        "translation": "「沒有意義，跳過吧！」"
      },
      {
        "time": 208.175,
        "end": 210.035,
        "text": "じゅうはちと にじゅうさん、さいごの くみ、",
        "section": 37,
        "translation": "十八和二十三，最後一組，"
      },
      {
        "time": 210.035,
        "end": 211.915,
        "text": "にせんにじゅうよねんを みてみよう！",
        "section": 37,
        "translation": "看看二零二四年！"
      },
      {
        "time": 211.915,
        "end": 214.555,
        "text": "だいじゅうろくだいの そうとうと ふくそうとう、",
        "section": 38,
        "translation": "第十六任總統與副總統，"
      },
      {
        "time": 214.555,
        "end": 215.984,
        "text": "だいじゅういっきの りっぽういん！",
        "section": 38,
        "translation": "第十一屆立法院！"
      },
      {
        "time": 215.984,
        "end": 217.555,
        "text": "「どちらも ななきを すすめたら、",
        "section": 39,
        "translation": "「如果兩邊都往後推七屆，"
      },
      {
        "time": 217.555,
        "end": 219.275,
        "text": "ぴったり あうんじゃ ないかな？」",
        "section": 39,
        "translation": "不就剛好對上了嗎？」"
      },
      {
        "time": 219.275,
        "end": 221.355,
        "text": "「だいとうりょう？ ふつうに みえるね、",
        "section": 40,
        "translation": "「總統？看起來很正常，"
      },
      {
        "time": 221.355,
        "end": 223.115,
        "text": "たいぺいしちょうから だいとうりょう！」",
        "section": 40,
        "translation": "從台北市長到總統！」"
      },
      {
        "time": 223.115,
        "end": 224.735,
        "text": "「でも どうして だいとうりょうに？",
        "section": 41,
        "translation": "「但為什麼要當總統？"
      },
      {
        "time": 224.735,
        "end": 226.515,
        "text": "れきしと なにか かんけいが ある？」",
        "section": 41,
        "translation": "跟歷史有什麼關係嗎？」"
      },
      {
        "time": 226.515,
        "end": 228.175,
        "text": "「れきしと かんけいが ないなら、",
        "section": 42,
        "translation": "「如果跟歷史沒有關係，"
      },
      {
        "time": 228.175,
        "end": 229.955,
        "text": "むりに なる ひつよう ないでしょう？」",
        "section": 42,
        "translation": "也不需要勉強去當吧？」"
      },
      {
        "time": 229.955,
        "end": 231.495,
        "text": "むっつの くみあわせ、",
        "section": 43,
        "translation": "六種組合，"
      },
      {
        "time": 231.495,
        "end": 232.705,
        "text": "むっつの ものがたり、",
        "section": 43,
        "translation": "六段故事，"
      },
      {
        "time": 233.195,
        "end": 235.335,
        "text": "すうじが つなぐ ふしぎな かいわ、",
        "section": 43,
        "translation": "數字串起不可思議的對話，"
      },
      {
        "time": 235.335,
        "end": 238.205,
        "text": "これが くみあわせの たいわ！",
        "section": 43,
        "translation": "這就是排列組合的對話！"
      }
